```csharp
using System;
using System.Threading;
using System.Threading.Tasks;

class Worker
{
    static void Stop(Thread worker, CancellationTokenSource cts)
    {
        // ruleid: no-thread-abort-csharp
        worker.Abort();
        // ok: no-thread-abort-csharp
        cts.Cancel();
        // ok: no-thread-abort-csharp
        worker.Join();
    }

    static void Kill(Thread t)
    {
        // ruleid: no-thread-abort-csharp
        t?.Abort();
    }

    static Task Schedule(Thread t) =>
        // ruleid: no-thread-abort-csharp
        Task.Run(() => t.Abort());

    static bool Check(Thread t, CancellationToken token)
    {
        // ok: no-thread-abort-csharp
        t.Interrupt();
        // ok: no-thread-abort-csharp
        return token.IsCancellationRequested;
    }
}
